from typing import Optional, Set, Tuple

Relation = Set[Tuple[int, int]]


def is_tangled(edges: Relation) -> Optional[Tuple[int, int]]:
    """Return a witnessing two-cycle (x, y) with (x, y) and (y, x) both present,
    or None if the relation is untangled. Self-loops (x, x) count as tangles."""
    for (x, y) in edges:
        if (y, x) in edges:
            return (x, y)
    return None


def is_asymmetric(edges: Relation) -> bool:
    """True iff no edge has a reverse and there are no self-loops."""
    return all((y, x) not in edges for (x, y) in edges)


if __name__ == "__main__":
    ladder = {(i, j) for i in range(5) for j in range(5) if i < j}  # (N, <)
    print("strict order <  tangled:", is_tangled(ladder), "asym:", is_asymmetric(ladder))
    two_cycle = {(0, 1), (1, 0)}
    print("two-cycle       tangled:", is_tangled(two_cycle), "asym:", is_asymmetric(two_cycle))
    print("self-loop       tangled:", is_tangled({(3, 3)}))

from typing import Iterable, Optional, Set, Tuple

Relation = Set[Tuple[int, int]]


def find_grading(vertices: Iterable[int], edges: Relation) -> Optional[dict]:
    """Kahn topological sort. Returns rank: V -> N with rank(a) < rank(b) for
    every edge (a, b) if the graph is acyclic (gradable), else None -- a tangle
    (cycle of some length) has no grading (the consistency dichotomy)."""
    verts = list(vertices)
    indeg = {v: 0 for v in verts}
    succ: dict = {v: [] for v in verts}
    for (a, b) in edges:
        succ[a].append(b)
        indeg[b] += 1
    queue = [v for v in verts if indeg[v] == 0]
    rank: dict = {}
    level, processed = 0, 0
    while queue:
        nxt = []
        for v in queue:
            rank[v] = level
            processed += 1
            for w in succ[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    nxt.append(w)
        queue, level = nxt, level + 1
    return rank if processed == len(verts) else None


if __name__ == "__main__":
    ladder = {(i, j) for i in range(5) for j in range(5) if i < j}
    print("grading of ladder:", find_grading(range(5), ladder))
    print("grading of 2-cycle:", find_grading([0, 1], {(0, 1), (1, 0)}))

from itertools import combinations, product
from typing import Callable, FrozenSet, Iterable


def russell_diagonal(universe: Iterable[int],
                     decode: Callable[[int], FrozenSet[int]]) -> FrozenSet[int]:
    """R = { x in U : x not in decode(x) }: provably unnamed by any code."""
    return frozenset(x for x in universe if x not in decode(x))


def decode_is_surjective(universe: Iterable[int],
                         decode: Callable[[int], FrozenSet[int]]) -> bool:
    U = list(universe)
    image = {decode(c) for c in U}
    for bits in product([False, True], repeat=len(U)):
        if frozenset(u for u, b in zip(U, bits) if b) not in image:
            return False
    return True


if __name__ == "__main__":
    U = [0, 1, 2]
    table = {0: frozenset({0, 1}), 1: frozenset({2}), 2: frozenset({0, 1, 2})}
    d = lambda c: table[c]
    R = russell_diagonal(U, d)
    print("Russell diagonal R =", set(R), "named by:",
          [c for c in U if d(c) == R])
    # Exhaustive: no decoding of a 2-element universe is surjective.
    U2 = [0, 1]
    subs = [frozenset(s) for r in range(3) for s in combinations(U2, r)]
    surj = any(decode_is_surjective(U2, lambda c, m={0: a, 1: b}: m[c])
               for a in subs for b in subs)
    print("any surjective decoding of a 2-element universe?", surj)

