"""Visualize the grading (topological level) of an acyclic hierarchy and the
failure of grading on a cyclic one, as layered node diagrams."""
import matplotlib.pyplot as plt


def kahn_levels(V, E):
    indeg = {v: 0 for v in V}; succ = {v: [] for v in V}
    for a, b in E: succ[a].append(b); indeg[b] += 1
    Q = [v for v in V if indeg[v] == 0]; lvl = {}; d = 0; seen = 0
    while Q:
        nx = []
        for v in Q:
            lvl[v] = d; seen += 1
            for w in succ[v]:
                indeg[w] -= 1
                if indeg[w] == 0: nx.append(w)
        Q = nx; d += 1
    return lvl if seen == len(V) else None


def plot(ax, V, E, title):
    lvl = kahn_levels(V, E)
    if lvl is None:
        ax.text(0.5, 0.5, "NO GRADING\n(cycle / tangle)", ha="center",
                va="center", color="crimson", fontsize=16, weight="bold")
        ax.set_title(title); ax.axis("off"); return
    from collections import defaultdict
    cols = defaultdict(list)
    for v, L in lvl.items(): cols[L].append(v)
    pos = {}
    for L, vs in cols.items():
        for k, v in enumerate(sorted(vs)): pos[v] = (L, k - (len(vs) - 1) / 2)
    for a, b in E:
        ax.annotate("", xy=pos[b], xytext=pos[a],
                    arrowprops=dict(arrowstyle="->", color="#4477aa", lw=1.5))
    for v, (x, y) in pos.items():
        ax.scatter([x], [y], s=500, color="#2a9d8f", zorder=3)
        ax.text(x, y, str(v), color="white", ha="center", va="center", zorder=4)
    ax.set_title(title); ax.set_xlabel("rank / level"); ax.set_yticks([])


V = list(range(6))
dag = {(0, 1), (0, 2), (1, 3), (2, 3), (3, 4), (3, 5)}
cyc = {(0, 1), (1, 2), (2, 0)}
fig, axes = plt.subplots(1, 2, figsize=(11, 5))
plot(axes[0], V, dag, "Acyclic hierarchy: grading exists")
plot(axes[1], [0, 1, 2], cyc, "3-cycle: no grading")
plt.tight_layout(); plt.savefig("grading.png", dpi=150)
